      const target = document.querySelector('section.cards--doing');
      const targetId = target.id;
      const dt = new DataTransfer();
      card.dispatchEvent(new DragEvent('dragstart', { bubbles: true, cancelable: true, dataTransfer: dt }));
      target.dispatchEvent(new DragEvent('dragover', { bubbles: true, cancelable: true, dataTransfer: dt }));
      target.dispatchEvent(new DragEvent('drop', { bubbles: true, cancelable: true, dataTransfer: dt }));
      card.dispatchEvent(new DragEvent('dragend', { bubbles: true, cancelable: true, dataTransfer: dt }));
      window.__immediateParent = card.closest('section.cards').id;
      window.__expectedTarget = targetId;
      window.__immediateSaveFinished = window.__saveFinished;
    JS

    immediate_parent = page.evaluate_script("window.__immediateParent")
    expected = page.evaluate_script("window.__expectedTarget")
    save_finished_immediate = page.evaluate_script("window.__immediateSaveFinished")
    save_started = page.evaluate_script("window.__saveStarted")

    puts "Immediate parent: #{immediate_parent}, expected: #{expected}"
    puts "Save started: #{save_started}, finished immediate: #{save_finished_immediate}"

    assert_equal expected, immediate_parent, "board should already be moved immediately after drop"
    assert_not save_finished_immediate, "save should not have finished yet (proves instant)"
    # Wait for save to finish, verify no shifting (still in target)
    sleep 2
    after_parent = page.evaluate_script("Array.from(document.querySelectorAll('article.card')).find(c => c.textContent.includes('Buy domain')).closest('section').id")
    puts "After save parent: #{after_parent}"
    assert_equal expected, after_parent, "nothing should shift after save"
    puts "INSTANT OK"
  end
end
